CREATE DATABASE ISO8583;
USE ISO8583;

CREATE TABLE ISO_ECHO_LOG ( id_echo int AUTO_INCREMENT, trace_number varchar(6) not null, request varchar(900) not null, response varchar(900) null , creation_date datetime  not null, CONSTRAINT PK_ID_ECHO PRIMARY KEY (id_echo) );

CREATE TABLE ISO_REVERSE_QUEUE ( id_queue int  AUTO_INCREMENT PRIMARY KEY, trace_number varchar(10) null, iso_message varchar(2000) not null, command varchar(10) not null, status int null);

CREATE TABLE CISO_OPERATION ( id_operation int AUTO_INCREMENT, name varchar(30) not null, code varchar(4) not null, creation_date datetime  not null, CONSTRAINT PK_ID_OPERATION PRIMARY KEY (id_operation) );

CREATE TABLE CISO_BIN ( id_bin int AUTO_INCREMENT, bin varchar(10) not null, bank varchar(80) not null, product varchar(80) not null, type varchar(20) not null, brand varchar(50) not null, creation_date datetime  not null, CONSTRAINT PK_ID_BIN PRIMARY KEY (id_bin) );

CREATE TABLE CISO_RESPONSE_CODE ( id_response_code int AUTO_INCREMENT, iso_code varchar(4) not null, description varchar(80) not null, device_description varchar(80) not null, creation_date datetime  not null, CONSTRAINT PK_ID_RESPONSE PRIMARY KEY (id_response_code) );

create table ISO_MESSAGE( id_message int AUTO_INCREMENT, id_operation int, trace_number varchar(10) not null, reference_number varchar(16) null, request varchar(2000) not null, response varchar(2000) null, creation_date datetime  not null, CONSTRAINT PK_ID_MESSAGE PRIMARY KEY (id_message, trace_number), CONSTRAINT FK_TRANSACTION_OPERATION FOREIGN KEY (id_operation)  REFERENCES CISO_OPERATION(id_operation));

CREATE TABLE ISO_TRANSACTION ( id_transaction int AUTO_INCREMENT, id_message int, id_response_code int, id_bin int, node varchar(10) null, amount  double null, cashback double  null, authorization varchar(10) null, last4 varchar(4) null, draft_capture varchar(4) null, reverse_code varchar(10) null, direct boolean null, cancelled boolean null, creation_date datetime not null, CONSTRAINT PK_ID_TRANSACTION PRIMARY KEY (id_transaction), CONSTRAINT FK_TRANSACTION_MESSAGE FOREIGN KEY (id_message)  REFERENCES ISO_MESSAGE(id_message), CONSTRAINT FK_TRANSACTION_RESPONSE FOREIGN KEY (id_response_code)  REFERENCES CISO_RESPONSE_CODE(id_response_code), CONSTRAINT FK_TRANSACTION_BIN FOREIGN KEY (id_bin)  REFERENCES CISO_BIN(id_bin));

CREATE TABLE ISO_API_LOG ( id_log int AUTO_INCREMENT not null, id_transaction int, id_request varchar(50) null, uri varchar(100) not null, method varchar(5) not null, request varchar(2000) not null, response varchar(2000) not null, ip varchar(20) not null, creation_date datetime  not null, CONSTRAINT PK_ID_API_LOG PRIMARY KEY (id_log), CONSTRAINT FK_API_LOG_TRANSACTION FOREIGN KEY (id_transaction) REFERENCES ISO_TRANSACTION(id_transaction));


